"```cpp
 #include <iostream>
 #include <vector>
 #include <map>
 #include <string>
 #include <random>
 #include <chrono>
 #include <thread>
 #include <queue>
 #include <algorithm>

 using namespace std;

 enum DeviceState { IDLE, CHECKING, DOWNLOADING, VERIFYING, INSTALLING, ROLLING_BACK, FAILED, PAUSED };

 struct Firmware {
  string version;
  string type;
  size_t size;
 };

 void log(const string& msg) {
  cout << ""[LOG] "" << msg << endl;
 }

 class Device {
 public:
  string id;
  string type;
  Firmware current;
  Firmware previous;
  DeviceState state = IDLE;
  size_t download_progress = 0;
  size_t chunk_size = 1024;
  double update_speed; // bytes per second
  double network_reliability = 0.95;
  double power_stability = 0.99;
  bool is_updating = false;
  Firmware target;

  Device(string i, string t, string ver, double speed) : id(i), type(t), update_speed(speed) {
  current.version = ver;
  current.type = t;
  current.size = 10000; // dummy size
  }

  void startUpdate(const Firmware& fw) {
  target = fw;
  state = CHECKING;
  is_updating = true;
  download_progress = 0;
  }

  void simulateTick(double dt, mt19937& gen) {
  uniform_real_distribution<> dis(0.0, 1.0);

  // Simulate network interruption for downloading
  bool network_interrupted = false;
  if (state == DOWNLOADING && dis(gen) <= (1 - network_reliability)) {
  log(""Network interrupt on "" + id);
  network_interrupted = true;
  state = PAUSED;
  }

  // Simulate power failure
  if ((state == DOWNLOADING || state == INSTALLING || state == VERIFYING) && dis(gen) <= (1 - power_stability)) {
  log(""Power failure on "" + id);
  recover();
  return;
  }

  // If paused from network, attempt to resume randomly
  if (state == PAUSED) {
  if (dis(gen) < 0.8) { // 20% chance to stay paused each tick
  log(""Still paused on "" + id);
  return;
  } else {
  state = DOWNLOADING;
  log(""Resumed from pause on "" + id);
  }
  }

  // No interruption, proceed with state machine
  switch (state) {
  case CHECKING:
  log(""Checking for update on "" + id);
  state = DOWNLOADING;
  break;
  case DOWNLOADING: {
  size_t remaining = target.size - download_progress;
  size_t bytes_this_tick = static_cast<size_t>(update_speed * dt);
  size_t chunk_download = min(chunk_size, remaining);
  size_t advance = min(bytes_this_tick, chunk_download);
  download_progress += advance;
  log(""Downloading on "" + id + "": "" + to_string(download_progress) + ""/"" + to_string(target.size));
  if (download_progress >= target.size) {
  state = VERIFYING;
  }
  break;
  }
  case VERIFYING:
  log(""Verifying on "" + id);
  bool success = dis(gen) > 0.1; // 90% success rate
  if (success) {
  previous = current;
  state = INSTALLING;
  } else {
  log(""Verification failed on "" + id);
  state = FAILED;
  }
  break;
  case INSTALLING:
  log(""Installing on "" + id);
  current = target;
  state = IDLE;
  is_updating = false;
  log(""Update successful on "" + id + "" to "" + current.version);
  break;
  case ROLLING_BACK:
  log(""Rolling back on "" + id);
  current = previous;
  state = IDLE;
  is_updating = false;
  log(""Rolled back on "" + id + "" to "" + current.version);
  break;
  case FAILED:
  log(""Handling failure on "" + id);
  if (previous.version != """") { // Assume previous exists
  state = ROLLING_BACK;
  } else {
  state = IDLE;
  is_updating = false;
  }
  break;
  default:
  break;
  }
  }

  void recover() {
  if (state == DOWNLOADING || state == PAUSED) {
  state = DOWNLOADING; // Resume download
  log(""Recovering download on "" + id);
  } else if (state == INSTALLING || state == VERIFYING) {
  state = FAILED; // Trigger rollback
  log(""Recovering by initiating rollback on "" + id);
  } else {
  state = IDLE;
  is_updating = false;
  }
  }

  string getStatus() {
  return id + "" ("" + type + ""): v"" + current.version + "" state: "" + to_string(state) + "" progress: "" + to_string(download_progress) + ""/"" + to_string(target.size);
  }
 };

 class UpdateManager {
 private:
  vector<Device> devices;
  map<string, Firmware> server_firmwares;
  queue<string> update_queue; // Queue of device IDs for update management

 public:
  void addDevice(const string& id, const string& type, const string& ver, double speed) {
  devices.emplace_back(id, type, ver, speed);
  }

  void setFirmware(const string& type, const string& ver, size_t size) {
  Firmware fw{ver, type, size};
  server_firmwares[type] = fw;
  }

  void queueUpdate(const string& id) {
  update_queue.push(id);
  log(""Queued update for "" + id);
  }

  void processUpdates() {
  // Process the queue, starting updates if not already updating (allows concurrency)
  size_t queue_size = update_queue.size();
  for (size_t i = 0; i < queue_size; ++i) {
  string id = update_queue.front();
  update_queue.pop();
  bool started = false;
  for (auto& d : devices) {
  if (d.id == id && !d.is_updating) {
  auto it = server_firmwares.find(d.type);
  if (it != server_firmwares.end() && stoi(it->second.version) > stoi(d.current.version)) {
  d.startUpdate(it->second);
  started = true;
  break;
  }
  }
  }
  if (!started) {
  // Requeue if couldn't start (e.g., already updating)
  update_queue.push(id);
  }
  }
  }

  void simulate(double duration, double dt) {
  random_device rd;
  mt19937 gen(rd());
  for (double t = 0; t < duration; t += dt) {
  processUpdates();
  for (auto& d : devices) {
  if (d.is_updating) {
  d.simulateTick(dt, gen);
  }
  }
  this_thread::sleep_for(chrono::milliseconds(static_cast<int>(dt * 1000)));
  }
  }

  void listDevices() {
  for (const auto& d : devices) {
  cout << d.getStatus() << endl;
  }
  }

  void printStatus(const string& id) {
  for (const auto& d : devices) {
  if (d.id == id) {
  cout << d.getStatus() << endl;
  return;
  }
  }
  cout << ""Device not found: "" << id << endl;
  }
 };

