#include <iostream> 
 #include <vector> 
 #include <map> 
 #include <string> 
 #include <random> 
 #include <chrono> 
 #include <thread> 
 #include <queue> 
 #include <algorithm> 
 #include <stdexcept> 

 using namespace std; 

 // Device operational states 
 enum class DeviceState { IDLE, CHECKING, DOWNLOADING, VERIFYING, INSTALLING, ROLLING_BACK, FAILED, PAUSED }; 

 // Firmware metadata 
 struct Firmware { 
  string version; 
  string type; 
  size_t size; 
 }; 

 // Logger for consistent debug output 
 void logMessage(const string& msg) { 
  cout << "[LOG] " << msg << endl; 
 } 

 // Utility function to safely parse integer versions 
 int safeVersionToInt(const string& version) { 
  try { 
  return stoi(version); 
  } catch (...) { 
  return -1; // invalid version 
  } 
 } 

 // IoT Device representation 
 class Device { 
 public: 
  string id; 
  string type; 
  Firmware currentFirmware; 
  Firmware previousFirmware; 
  Firmware targetFirmware; 

  DeviceState state = DeviceState::IDLE; 
  size_t downloadProgress = 0; 
  size_t chunkSize = 1024; 
  double updateSpeed; // bytes per second 
  double networkReliability = 0.95; 
  double powerStability = 0.99; 
  bool isUpdating = false; 

  Device(const string& id_, const string& type_, const string& version_, double speed) 
  : id(id_), type(type_), updateSpeed(speed) 
  { 
  currentFirmware = {version_, type_, 10000}; // default dummy firmware 
  } 

  // Start OTA update 
  void startUpdate(const Firmware& fw) { 
  targetFirmware = fw; 
  state = DeviceState::CHECKING; 
  isUpdating = true; 
  downloadProgress = 0; 
  } 

  // Main update tick simulation 
  void simulateTick(double dt, mt19937& gen) { 
  uniform_real_distribution<> dis(0.0, 1.0); 

  // Network interruption simulation 
  if (state == DeviceState::DOWNLOADING && dis(gen) > networkReliability) { 
  logMessage("Network interruption on " + id); 
  state = DeviceState::PAUSED; 
  } 

  // Power failure simulation 
  if ((state == DeviceState::DOWNLOADING || state == DeviceState::INSTALLING || state == DeviceState::VERIFYING) 
  && dis(gen) > powerStability) { 
  logMessage("Power failure on " + id); 
  recover(); 
  return; 
  } 

  // Resume from pause 
  if (state == DeviceState::PAUSED) { 
  if (dis(gen) < 0.8) { // 80% chance to remain paused 
  logMessage("Still paused on " + id); 
  return; 
  } else { 
  logMessage("Resumed from pause on " + id); 
  state = DeviceState::DOWNLOADING; 
  } 
  } 

  // State machine for update workflow 
  switch (state) { 
  case DeviceState::CHECKING: 
  logMessage("Checking update for " + id); 
  state = DeviceState::DOWNLOADING; 
  break; 

  case DeviceState::DOWNLOADING: { 
  size_t remaining = targetFirmware.size - downloadProgress; 
  size_t bytesThisTick = static_cast<size_t>(updateSpeed * dt); 
  size_t advance = min(bytesThisTick, min(chunkSize, remaining)); 
  downloadProgress += advance; 
  logMessage("Downloading on " + id + ": " + to_string(downloadProgress) + "/" + to_string(targetFirmware.size)); 

  if (downloadProgress >= targetFirmware.size) { 
  state = DeviceState::VERIFYING; 
  } 
  break; 
  } 

  case DeviceState::VERIFYING: { 
  logMessage("Verifying update on " + id); 
  bool verified = dis(gen) > 0.1; // 90% success 
  if (verified) { 
  previousFirmware = currentFirmware; 
  state = DeviceState::INSTALLING; 
  } else { 
  logMessage("Verification failed on " + id); 
  state = DeviceState::FAILED; 
  } 
  break; 
  } 

  case DeviceState::INSTALLING: 
  logMessage("Installing update on " + id); 
  currentFirmware = targetFirmware; 
  isUpdating = false; 
  state = DeviceState::IDLE; 
  logMessage("Update successful: " + id + " -> v" + currentFirmware.version); 
  break; 

  case DeviceState::ROLLING_BACK: 
  logMessage("Rolling back on " + id); 
  currentFirmware = previousFirmware; 
  isUpdating = false; 
  state = DeviceState::IDLE; 
  logMessage("Rollback complete on " + id + " -> v" + currentFirmware.version); 
  break; 

  case DeviceState::FAILED: 
  logMessage("Handling failure on " + id); 
  if (!previousFirmware.version.empty()) { 
  state = DeviceState::ROLLING_BACK; 
  } else { 
  isUpdating = false; 
  state = DeviceState::IDLE; 
  } 
  break; 

  default: 
  break; 
  } 
  } 

  // Recovery from failures 
  void recover() { 
  if (state == DeviceState::DOWNLOADING || state == DeviceState::PAUSED) { 
  logMessage("Recovering download on " + id); 
  state = DeviceState::DOWNLOADING; 
  } else if (state == DeviceState::INSTALLING || state == DeviceState::VERIFYING) { 
  logMessage("Recovering by rollback on " + id); 
  state = DeviceState::FAILED; 
  } else { 
  isUpdating = false; 
  state = DeviceState::IDLE; 
  } 
  } 

  // Device status string 
  string getStatus() const { 
  return id + " (" + type + "): v" + currentFirmware.version + 
  " state=" + to_string(static_cast<int>(state)) + 
  " progress=" + to_string(downloadProgress) + "/" + to_string(targetFirmware.size); 
  } 
 }; 

 // Update Manager orchestrates OTA process 
 class UpdateManager { 
 private: 
  vector<Device> devices; 
  map<string, Firmware> serverFirmwares; 
  queue<string> updateQueue; 

 public: 
  // Add device 
  void addDevice(const string& id, const string& type, const string& version, double speed) { 
  if (id.empty() || type.empty() || version.empty() || speed <= 0) { 
  cerr << "[ERROR] Invalid device parameters" << endl; 
  return; 
  } 
  devices.emplace_back(id, type, version, speed); 
  logMessage("Device added: " + id); 
  } 

  // Upload firmware to server 
  void setFirmware(const string& type, const string& version, size_t size) { 
  if (type.empty() || version.empty() || size == 0) { 
  cerr << "[ERROR] Invalid firmware parameters" << endl; 
  return; 
  } 
  serverFirmwares[type] = {version, type, size}; 
  logMessage("Firmware set for type " + type + " -> v" + version); 
  } 

  // Queue a device for update 
  void queueUpdate(const string& id) { 
  updateQueue.push(id); 
  logMessage("Update queued for " + id); 
  } 

  // Process queued updates 
  void processUpdates() { 
  size_t qSize = updateQueue.size(); 
  for (size_t i = 0; i < qSize; ++i) { 
  string id = updateQueue.front(); 
  updateQueue.pop(); 
  bool started = false; 
  for (auto& dev : devices) { 
  if (dev.id == id && !dev.isUpdating) { 
  auto it = serverFirmwares.find(dev.type); 
  if (it != serverFirmwares.end() && safeVersionToInt(it->second.version) > safeVersionToInt(dev.currentFirmware.version)) { 
  dev.startUpdate(it->second); 
  started = true; 
  break; 
  } 
  } 
  } 
  if (!started) { 
  updateQueue.push(id); // Requeue if update not started 
  } 
  } 
  } 

  // Run simulation loop 
  void simulate(double duration, double tick) { 
  if (duration <= 0 || tick <= 0) { 
  cerr << "[ERROR] Invalid simulation parameters" << endl; 
  return; 
  } 
  random_device rd; 
  mt19937 gen(rd()); 
  for (double t = 0; t < duration; t += tick) { 
  processUpdates(); 
  for (auto& dev : devices) { 
  if (dev.isUpdating) { 
  dev.simulateTick(tick, gen); 
  } 
  } 
  this_thread::sleep_for(chrono::milliseconds(static_cast<int>(tick * 1000))); 
  } 
  } 

  // List all devices 
  void listDevices() const { 
  for (const auto& dev : devices) { 
  cout << dev.getStatus() << endl; 
  } 
  } 

  // Print single device status 
  void printStatus(const string& id) const { 
  for (const auto& dev : devices) { 
  if (dev.id == id) { 
  cout << dev.getStatus() << endl; 
  return; 
  } 
  } 
  cerr << "[ERROR] Device not found: " << id << endl; 
  } 
 }; 

 // CLI Interface 
 int main() { 
  UpdateManager manager; 
  string command; 

  cout << "OTA Simulator CLI. Commands: add_device, set_firmware, queue_update, simulate, list_devices, status, exit\n"; 

  while (true) { 
  cout << "> "; 
  if (!(cin >> command)) break; 

  if (command == "add_device") { 
  string id, type, version; 
  double speed; 
  cin >> id >> type >> version >> speed; 
  manager.addDevice(id, type, version, speed); 

  } else if (command == "set_firmware") { 
  string type, version; 
  size_t size; 
  cin >> type >> version >> size; 
  manager.setFirmware(type, version, size); 

  } else if (command == "queue_update") { 
  string id; 
  cin >> id; 
  manager.queueUpdate(id); 

  } else if (command == "simulate") { 
  double duration, tick; 
  cin >> duration >> tick; 
  manager.simulate(duration, tick); 

  } else if (command == "list_devices") { 
  manager.listDevices(); 

  } else if (command == "status") { 
  string id; 
  cin >> id; 
  manager.printStatus(id); 

  } else if (command == "exit") { 
  break; 

  } else { 
  cerr << "[ERROR] Unknown command\n"; 
  } 
  } 
  return 0; 
 }

