  NONE,
  NETWORK_TIMEOUT,
  POWER_FAILURE,
  CHECKSUM_MISMATCH,
  INSUFFICIENT_MEMORY,
  INCOMPATIBLE_VERSION
 };

 // Log entry structure
 struct LogEntry {
