 #include <sstream> 
 #include <iomanip> 
 #include <algorithm> 
 #include <atomic> 
 #include <memory> 
 #include <ctime> 

 // Firmware version structure 
 struct FirmwareVersion { 
  int major; 
  int minor; 
  int patch; 

  FirmwareVersion(int maj = 0, int min = 0, int p = 0) 
  : major(maj), minor(min), patch(p) {} 

  std::string toString() const { 
  return std::to_string(major) + "." + 
  std::to_string(minor) + "." + 
  std::to_string(patch); 
  } 

  bool operator<(const FirmwareVersion& other) const { 
  if (major != other.major) return major < other.major; 
  if (minor != other.minor) return minor < other.minor; 
  return patch < other.patch; 
  } 

  bool operator==(const FirmwareVersion& other) const { 
  return major == other.major && 
  minor == other.minor && 
  patch == other.patch; 
  } 
 }; 

 // Device types with different characteristics 
 enum class DeviceType { 
  SENSOR_BASIC, 
  SENSOR_ADVANCED, 
  GATEWAY, 
  CONTROLLER 
 }; 

 // Update status 
 enum class UpdateStatus { 
  IDLE, 
  QUEUED, 
  DOWNLOADING, 
  INSTALLING, 
  VERIFYING, 
  COMPLETED, 
  FAILED, 
  ROLLED_BACK 
 }; 

 // Failure types 
 enum class FailureType { 
  NONE, 
  NETWORK_TIMEOUT, 
  POWER_FAILURE, 
  CHECKSUM_MISMATCH, 
  INSUFFICIENT_MEMORY, 
  INCOMPATIBLE_VERSION 
 }; 

 // Log entry structure 
 struct LogEntry { 
  std::time_t timestamp; 
  std::string deviceId; 
  std::string message; 
  std::string severity; // INFO, WARNING, ERROR 

  std::string toString() const { 
  char timeStr[100]; 
  std::strftime(timeStr, sizeof(timeStr), "%Y-%m-%d %H:%M:%S", 
  std::localtime(&timestamp)); 
  return std::string(timeStr) + " [" + severity + "] " + 
  deviceId + ": " + message; 
  } 
 }; 

 // Firmware package 
 struct FirmwarePackage { 
  FirmwareVersion version; 
  size_t totalSize; 
  size_t chunkSize; 
  std::vector<std::string> chunks; // Simulated firmware chunks 
  std::string checksum; 

  FirmwarePackage(FirmwareVersion v, size_t size = 1024 * 1024) 
  : version(v), totalSize(size), chunkSize(4096) { 
  // Simulate firmware chunks 
  size_t numChunks = (totalSize + chunkSize - 1) / chunkSize; 
  for (size_t i = 0; i < numChunks; ++i) { 
  chunks.push_back("CHUNK_" + std::to_string(i)); 
  } 
  checksum = "SHA256_" + version.toString(); 
  } 
 }; 

 // Device class 
 class Device { 
 private: 
  std::string id; 
  DeviceType type; 
  FirmwareVersion currentVersion; 
  FirmwareVersion previousVersion; 
  UpdateStatus status; 
  size_t downloadProgress; 
  size_t downloadSpeed; // bytes per second 
  std::atomic<bool> powerOn; 
  std::atomic<bool> networkConnected; 
  FailureType lastFailure; 
  std::vector<std::string> downloadedChunks; 
  std::mutex deviceMutex; 

 public: 
  Device(const std::string& deviceId, DeviceType t, FirmwareVersion v) 
  : id(deviceId), type(t), currentVersion(v), previousVersion(v), 
  status(UpdateStatus::IDLE), downloadProgress(0), 
  powerOn(true), networkConnected(true), 
  lastFailure(FailureType::NONE) { 

  // Set download speed based on device type 
  switch (type) { 
  case DeviceType::SENSOR_BASIC: 
  downloadSpeed = 10 * 1024; // 10 KB/s 
  break; 
  case DeviceType::SENSOR_ADVANCED: 
  downloadSpeed = 50 * 1024; // 50 KB/s 
  break; 
  case DeviceType::GATEWAY: 
  downloadSpeed = 100 * 1024; // 100 KB/s 
  break; 
  case DeviceType::CONTROLLER: 
  downloadSpeed = 200 * 1024; // 200 KB/s 
  break; 
  } 
  } 

  std::string getId() const { return id; } 
  DeviceType getType() const { return type; } 
  FirmwareVersion getCurrentVersion() const { return currentVersion; } 
  UpdateStatus getStatus() const { return status; } 
  size_t getDownloadProgress() const { return downloadProgress; } 
  bool isPowerOn() const { return powerOn.load(); } 
  bool isNetworkConnected() const { return networkConnected.load(); } 
  FailureType getLastFailure() const { return lastFailure; } 

  void setStatus(UpdateStatus s) { 
  std::lock_guard<std::mutex> lock(deviceMutex); 
  status = s; 
  } 

  void setPowerOn(bool on) { powerOn.store(on); } 
  void setNetworkConnected(bool connected) { networkConnected.store(connected); } 

  bool downloadChunk(const std::string& chunk) { 
  std::lock_guard<std::mutex> lock(deviceMutex); 
  if (!powerOn || !networkConnected) { 
  return false; 
  } 
  downloadedChunks.push_back(chunk); 
  downloadProgress = downloadedChunks.size(); 
  return true; 
  } 

  void clearDownloadedChunks() { 
  std::lock_guard<std::mutex> lock(deviceMutex); 
  downloadedChunks.clear(); 
  downloadProgress = 0; 
  } 

  bool installFirmware(const FirmwareVersion& newVersion) { 
  std::lock_guard<std::mutex> lock(deviceMutex); 
  if (!powerOn) { 
  lastFailure = FailureType::POWER_FAILURE; 
  return false; 
  } 
  previousVersion = currentVersion; 
  currentVersion = newVersion; 
  return true; 
  } 

  void rollback() { 
  std::lock_guard<std::mutex> lock(deviceMutex); 
  currentVersion = previousVersion; 
  status = UpdateStatus::ROLLED_BACK; 
  } 

  void setFailure(FailureType failure) { 
  std::lock_guard<std::mutex> lock(deviceMutex); 
  lastFailure = failure; 
  status = UpdateStatus::FAILED; 
  } 

  std::string getDeviceTypeString() const { 
  switch (type) { 
  case DeviceType::SENSOR_BASIC: return "Basic Sensor"; 
  case DeviceType::SENSOR_ADVANCED: return "Advanced Sensor"; 
  case DeviceType::GATEWAY: return "Gateway"; 
  case DeviceType::CONTROLLER: return "Controller"; 
  default: return "Unknown"; 
  } 
  } 

  std::string getStatusString() const { 
  switch (status) { 
  case UpdateStatus::IDLE: return "Idle"; 
  case UpdateStatus::QUEUED: return "Queued"; 
  case UpdateStatus::DOWNLOADING: return "Downloading"; 
  case UpdateStatus::INSTALLING: return "Installing"; 
  case UpdateStatus::VERIFYING: return "Verifying"; 
  case UpdateStatus::COMPLETED: return "Completed"; 
  case UpdateStatus::FAILED: return "Failed"; 
  case UpdateStatus::ROLLED_BACK: return "Rolled Back"; 
  default: return "Unknown"; 
  } 
  } 
 }; 

 // OTA Update Manager 
 class OTAUpdateManager { 
 private: 
  std::map<std::string, std::shared_ptr<Device>> devices; 
  std::map<FirmwareVersion, FirmwarePackage> firmwareRepository; 
  std::queue<std::pair<std::string, FirmwareVersion>> updateQueue; 
  std::vector<LogEntry> logs; 
  std::mutex managerMutex; 
  std::mutex queueMutex; 
  std::mutex logMutex; 
  std::condition_variable queueCV; 
  std::atomic<bool> running; 
  std::thread updateThread; 
  std::random_device rd; 
  std::mt19937 gen; 
  std::uniform_real_distribution<> failureDist; 

  void log(const std::string& deviceId, const std::string& message, 
  const std::string& severity = "INFO") { 
  std::lock_guard<std::mutex> lock(logMutex); 
  LogEntry entry; 
  entry.timestamp = std::time(nullptr); 
  entry.deviceId = deviceId; 
  entry.message = message; 
  entry.severity = severity; 
  logs.push_back(entry); 

  // Keep only last 1000 logs 
  if (logs.size() > 1000) { 
  logs.erase(logs.begin()); 
  } 
  } 

  void processUpdateQueue() { 
  while (running) { 
  std::unique_lock<std::mutex> lock(queueMutex); 
  queueCV.wait(lock, [this] { return !updateQueue.empty() || !running; }); 

  if (!running) break; 

  auto update = updateQueue.front(); 
  updateQueue.pop(); 
  lock.unlock(); 

  performUpdate(update.first, update.second); 
  } 
  } 

  void performUpdate(const std::string& deviceId, const FirmwareVersion& targetVersion) { 
  auto deviceIt = devices.find(deviceId); 
  if (deviceIt == devices.end()) { 
  log(deviceId, "Device not found", "ERROR"); 
  return; 
  } 

  auto device = deviceIt->second; 
  auto packageIt = firmwareRepository.find(targetVersion); 
  if (packageIt == firmwareRepository.end()) { 
  log(deviceId, "Firmware package not found: " + targetVersion.toString(), "ERROR"); 
  device->setFailure(FailureType::INCOMPATIBLE_VERSION); 
  return; 
  } 

  const FirmwarePackage& package = packageIt->second; 

  // Start update process 
  log(deviceId, "Starting update to version " + targetVersion.toString()); 
  device->setStatus(UpdateStatus::DOWNLOADING); 
  device->clearDownloadedChunks(); 

  // Download phase with chunk simulation 
  for (size_t i = 0; i < package.chunks.size(); ++i) { 
  // Simulate network interruption 
  if (failureDist(gen) < 0.05) { // 5% chance 
  device->setNetworkConnected(false); 
  log(deviceId, "Network connection lost during download", "ERROR"); 
  device->setFailure(FailureType::NETWORK_TIMEOUT); 

  // Attempt recovery after delay 
  std::this_thread::sleep_for(std::chrono::seconds(2)); 
  device->setNetworkConnected(true); 
  log(deviceId, "Network connection restored, retrying..."); 
  i--; // Retry the same chunk 
  continue; 
  } 

  // Simulate power failure 
  if (failureDist(gen) < 0.02) { // 2% chance 
  device->setPowerOn(false); 
  log(deviceId, "Power failure during download", "ERROR"); 
  device->setFailure(FailureType::POWER_FAILURE); 

  // Simulate power restoration 
  std::this_thread::sleep_for(std::chrono::seconds(3)); 
  device->setPowerOn(true); 
  log(deviceId, "Power restored, resuming download from chunk " + 
  std::to_string(device->getDownloadProgress())); 
  i = device->getDownloadProgress() - 1; // Resume from last chunk 
  continue; 
  } 

  if (!device->downloadChunk(package.chunks[i])) { 
  log(deviceId, "Failed to download chunk " + std::to_string(i), "ERROR"); 
  return; 
  } 

  // Simulate download delay based on device speed 
  size_t chunkTime = (package.chunkSize * 1000) / device->getDownloadProgress(); 
  std::this_thread::sleep_for(std::chrono::milliseconds(chunkTime / 10)); // Speed up simulation 
  } 

  log(deviceId, "Download completed, starting installation"); 
  device->setStatus(UpdateStatus::INSTALLING); 

  // Installation phase 
  std::this_thread::sleep_for(std::chrono::seconds(2)); 

  // Simulate installation failure 
  if (failureDist(gen) < 0.03) { // 3% chance 
  log(deviceId, "Installation failed", "ERROR"); 
  device->setFailure(FailureType::CHECKSUM_MISMATCH); 

  // Attempt rollback 
  log(deviceId, "Attempting rollback to previous version"); 
  device->rollback(); 
  log(deviceId, "Rollback completed successfully"); 
  return; 
  } 

  // Verification phase 
  device->setStatus(UpdateStatus::VERIFYING); 
  log(deviceId, "Verifying firmware integrity"); 
  std::this_thread::sleep_for(std::chrono::seconds(1)); 

  // Complete update 
  if (device->installFirmware(targetVersion)) { 
  device->setStatus(UpdateStatus::COMPLETED); 
  log(deviceId, "Update completed successfully to version " + targetVersion.toString()); 
  } else { 
  log(deviceId, "Update verification failed", "ERROR"); 
  device->rollback(); 
  } 
  } 

 public: 
  OTAUpdateManager() : running(true), gen(rd()), failureDist(0.0, 1.0) { 
  updateThread = std::thread(&OTAUpdateManager::processUpdateQueue, this); 
  } 

  ~OTAUpdateManager() { 
  running = false; 
  queueCV.notify_all(); 
  if (updateThread.joinable()) { 
  updateThread.join(); 
  } 
  } 

  void addDevice(const std::string& deviceId, DeviceType type, 
  const FirmwareVersion& version) { 
  std::lock_guard<std::mutex> lock(managerMutex); 
  devices[deviceId] = std::make_shared<Device>(deviceId, type, version); 
  log(deviceId, "Device registered with firmware " + version.toString()); 
  } 

  void addFirmwarePackage(const FirmwareVersion& version, size_t size = 1024 * 1024) { 
  std::lock_guard<std::mutex> lock(managerMutex); 
  firmwareRepository.emplace(version, FirmwarePackage(version, size)); 
  log("SYSTEM", "Firmware package " + version.toString() + " added to repository"); 
  } 

  void queueUpdate(const std::string& deviceId, const FirmwareVersion& targetVersion) { 
  { 
  std::lock_guard<std::mutex> lock(queueMutex); 
  updateQueue.push({deviceId, targetVersion}); 

  auto deviceIt = devices.find(deviceId); 
  if (deviceIt != devices.end()) { 
  deviceIt->second->setStatus(UpdateStatus::QUEUED); 
  } 
  } 
  queueCV.notify_one(); 
  log(deviceId, "Update queued for version " + targetVersion.toString()); 
  } 

  void displayDeviceStatus() { 
  std::lock_guard<std::mutex> lock(managerMutex); 
  std::cout << "\n=== Device Status ===" << std::endl; 
  std::cout << std::left << std::setw(15) << "Device ID" 
  << std::setw(20) << "Type" 
  << std::setw(15) << "Current Ver" 
  << std::setw(15) << "Status" 
  << std::setw(10) << "Progress" 
  << std::setw(10) << "Power" 
  << std::setw(10) << "Network" << std::endl; 
  std::cout << std::string(100, '-') << std::endl; 

  for (const auto& pair : devices) { 
  const auto& device = pair.second; 
  std::cout << std::left << std::setw(15) << device->getId() 
  << std::setw(20) << device->getDeviceTypeString() 
  << std::setw(15) << device->getCurrentVersion().toString() 
  << std::setw(15) << device->getStatusString() 
  << std::setw(10) << device->getDownloadProgress() 
  << std::setw(10) << (device->isPowerOn() ? "ON" : "OFF") 
  << std::setw(10) << (device->isNetworkConnected() ? "YES" : "NO") 
  << std::endl; 
  } 
  } 

  void displayUpdateQueue() { 
  std::lock_guard<std::mutex> lock(queueMutex); 
  std::cout << "\n=== Update Queue ===" << std::endl; 
  std::cout << "Queue size: " << updateQueue.size() << std::endl; 

  // Create temporary queue to display contents 
  std::queue<std::pair<std::string, FirmwareVersion>> tempQueue = updateQueue; 
  int position = 1; 
  while (!tempQueue.empty()) { 
  auto update = tempQueue.front(); 
  tempQueue.pop(); 
  std::cout << position++ << ". Device: " << update.first 
  << " -> Version: " << update.second.toString() << std::endl; 
  } 
  } 

  void displayLogs(int count = 20) { 
  std::lock_guard<std::mutex> lock(logMutex); 
  std::cout << "\n=== Recent Logs ===" << std::endl; 

  int start = std::max(0, static_cast<int>(logs.size()) - count); 
  for (int i = start; i < logs.size(); ++i) { 
  std::cout << logs[i].toString() << std::endl; 
  } 
  } 

  void simulateNetworkOutage(const std::string& deviceId) { 
  auto deviceIt = devices.find(deviceId); 
  if (deviceIt != devices.end()) { 
  deviceIt->second->setNetworkConnected(false); 
  log(deviceId, "Network outage simulated", "WARNING"); 
  } 
  } 

  void simulatePowerFailure(const std::string& deviceId) { 
  auto deviceIt = devices.find(deviceId); 
  if (deviceIt != devices.end()) { 
  deviceIt->second->setPowerOn(false); 
  log(deviceId, "Power failure simulated", "WARNING"); 
  } 
  } 

  void restoreDevice(const std::string& deviceId) { 
  auto deviceIt = devices.find(deviceId); 
  if (deviceIt != devices.end()) { 
  deviceIt->second->setPowerOn(true); 
  deviceIt->second->setNetworkConnected(true); 
  log(deviceId, "Device restored to normal operation"); 
  } 
  } 
 }; 

 // CLI Interface 
 class CLIInterface { 
 private: 
  OTAUpdateManager& manager; 
  bool running; 

  void printHelp() { 
  std::cout << "\n=== OTA Update Simulator Commands ===" << std::endl; 
  std::cout << "1. status - Display all device status" << std::endl; 
  std::cout << "2. queue - Display update queue" << std::endl; 
  std::cout << "3. logs [n] - Display last n logs (default: 20)" << std::endl; 
  std::cout << "4. update <device_id> <version> - Queue firmware update" << std::endl; 
  std::cout << "5. add-device <id> <type> <version> - Add new device" << std::endl; 
  std::cout << "6. add-firmware <version> [size] - Add firmware package" << std::endl; 
  std::cout << "7. fail-network <device_id> - Simulate network failure" << std::endl; 
  std::cout << "8. fail-power <device_id> - Simulate power failure" << std::endl; 
  std::cout << "9. restore <device_id> - Restore device connectivity" << std::endl; 
  std::cout << "10. help - Display this help" << std::endl; 
  std::cout << "11. quit - Exit simulator" << std::endl; 
  } 

  DeviceType parseDeviceType(const std::string& typeStr) { 
  if (typeStr == "basic") return DeviceType::SENSOR_BASIC; 
  if (typeStr == "advanced") return DeviceType::SENSOR_ADVANCED; 
  if (typeStr == "gateway") return DeviceType::GATEWAY; 
  if (typeStr == "controller") return DeviceType::CONTROLLER; 
  return DeviceType::SENSOR_BASIC; 
  } 

  FirmwareVersion parseVersion(const std::string& versionStr) { 
  std::istringstream iss(versionStr); 
  int major = 0, minor = 0, patch = 0; 
  char dot; 
  iss >> major >> dot >> minor >> dot >> patch; 
  return FirmwareVersion(major, minor, patch); 
  } 

 public: 
  CLIInterface(OTAUpdateManager& mgr) : manager(mgr), running(true) {} 

  void run() { 
  printHelp(); 

  std::string line; 
  while (running) { 
  std::cout << "\n> "; 
  std::getline(std::cin, line); 

  std::istringstream iss(line); 
  std::string command; 
  iss >> command; 

  if (command == "status") { 
  manager.displayDeviceStatus(); 
  } 
  else if (command == "queue") { 
  manager.displayUpdateQueue(); 
  } 
  else if (command == "logs") { 
  int count = 20; 
  iss >> count; 
  manager.displayLogs(count); 
  } 
  else if (command == "update") { 
  std::string deviceId, versionStr; 
  iss >> deviceId >> versionStr; 
  if (!deviceId.empty() && !versionStr.empty()) { 
  FirmwareVersion version = parseVersion(versionStr); 
  manager.queueUpdate(deviceId, version); 
  std::cout << "Update queued for device " << deviceId << std::endl; 
  } else { 
  std::cout << "Usage: update <device_id> <version>" << std::endl; 
  } 
  } 
  else if (command == "add-device") { 
  std::string deviceId, typeStr, versionStr; 
  iss >> deviceId >> typeStr >> versionStr; 
  if (!deviceId.empty() && !typeStr.empty() && !versionStr.empty()) { 
  DeviceType type = parseDeviceType(typeStr); 
  FirmwareVersion version = parseVersion(versionStr); 
  manager.addDevice(deviceId, type, version); 
  std::cout << "Device " << deviceId << " added" << std::endl; 
  } else { 
  std::cout << "Usage: add-device <id> <type> <version>" << std::endl; 
  std::cout << "Types: basic, advanced, gateway, controller" << std::endl; 
  } 
  } 
  else if (command == "add-firmware") { 
  std::string versionStr; 
  size_t size = 1024 * 1024; 
  iss >> versionStr >> size; 
  if (!versionStr.empty()) { 
  FirmwareVersion version = parseVersion(versionStr); 
  manager.addFirmwarePackage(version, size); 
  std::cout << "Firmware package " << versionStr << " added" << std::endl; 
  } else { 
  std::cout << "Usage: add-firmware <version> [size]" << std::endl; 
  } 
  } 
  else if (command == "fail-network") { 
  std::string deviceId; 
  iss >> deviceId; 
  if (!deviceId.empty()) { 
  manager.simulateNetworkOutage(deviceId); 
  std::cout << "Network failure simulated for " << deviceId << std::endl; 
  } else { 
  std::cout << "Usage: fail-network <device_id>" << std::endl; 
  } 
  } 
  else if (command == "fail-power") { 
  std::string deviceId; 
  iss >> deviceId; 
  if (!deviceId.empty()) { 
  manager.simulatePowerFailure(deviceId); 
  std::cout << "Power failure simulated for " << deviceId << std::endl; 
  } else { 
  std::cout << "Usage: fail-power <device_id>" << std::endl; 
  } 
  } 
  else if (command == "restore") { 
  std::string deviceId; 
  iss >> deviceId; 
  if (!deviceId.empty()) { 
  manager.restoreDevice(deviceId); 
  std::cout << "Device " << deviceId << " restored" << std::endl; 
  } else { 
  std::cout << "Usage: restore <device_id>" << std::endl; 
  } 
  } 
  else if (command == "help") { 
  printHelp(); 
  } 
  else if (command == "quit" || command == "exit") { 
  running = false; 
  std::cout << "Exiting OTA Update Simulator..." << std::endl; 
  } 
  else if (!command.empty()) { 
  std::cout << "Unknown command: " << command << std::endl; 
  std::cout << "Type 'help' for available commands" << std::endl; 
  } 
  } 
  } 
 }; 

