  if (weekMap.isEmpty()) continue;

  int maxWeek = weekMap.lastKey();

  // Collect units for the past 8 weeks (use 0 if missing)
  List<Integer> recentUnits = new ArrayList<>();
  for (int i = 0; i < 8; i++) {
  int w = maxWeek - i;
  int u = weekMap.getOrDefault(w, 0);
  recentUnits.add(u);
  }

  // Calculate mean
  double sum = 0;
  for (int u : recentUnits) {
  sum += u;
  }
