  double diff = u - mean;
  sumSq += diff * diff;
  }
  double variance = sumSq / 7.0; // n-1 for sample
  double stdDev = Math.sqrt(variance);

  // Flag if coefficient of variation > 0.3 (30% variation)
  boolean flagged = (mean > 0) && (stdDev / mean > 0.3);

  // Predicted units (rounded average)
