// ===== Configuration ===== 
 private static final int WEEKS_FOR_AVERAGE = 8; // lookback window 
 private static final int WEEKS_TO_PREDICT = 4; // horizon 
 private static final double HIGH_VAR_CV_THRESHOLD = 0.50; // flag if CV > 50% 

 // Defaults if no CLI args provided 
 private static final String DEFAULT_INPUT_FILE = "sales_data.csv"; 
 private static final String DEFAULT_OUTPUT_FILE = "demand_predictions.csv"; 

 // ===== Data Models ===== 

 /** Immutable record for a single row of sales. */ 
 static class SalesRecord { 
  final String skuId; 
  final int weekNumber; 
  final int unitsSold; 

  SalesRecord(String skuId, int weekNumber, int unitsSold) { 
  this.skuId = skuId; 
  this.weekNumber = weekNumber; 
  this.unitsSold = unitsSold; 
  } 
 } 

 /** Holds per-SKU computed stats and predictions. */ 
 static class PredictionResult { 
  final String skuId; 
  double mean; // average of last <= 8 weeks 
  double stdDev; // sample standard deviation 
  double coeffVar; // stdDev / mean (if mean > 0) 
  boolean highVariance; // coeffVar > threshold 
  final int[] nextWeeks; // next 4 weeks predictions (rounded mean) 

  PredictionResult(String skuId) { 
  this.skuId = skuId; 
  this.nextWeeks = new int[WEEKS_TO_PREDICT]; 
  } 
 } 

 // ===== Main ===== 

 public static void main(String[] args) { 
  // Special helper: create a sample file and exit. 
  if (args.length == 1 && "--make-sample".equalsIgnoreCase(args[0])) { 
  try { 
  createSampleInputFile(DEFAULT_INPUT_FILE); 
  System.out.println("Sample file written: " + DEFAULT_INPUT_FILE); 
  } catch (IOException e) { 
  System.err.println("Failed to create sample file: " + e.getMessage()); 
  System.exit(1); 
  } 
  return; 
  } 

  // Resolve input/output paths 
  final String inputPath; 
  final String outputPath; 
  if (args.length == 0) { 
  inputPath = DEFAULT_INPUT_FILE; 
  outputPath = DEFAULT_OUTPUT_FILE; 
  } else if (args.length == 2) { 
  inputPath = args[0]; 
  outputPath = args[1]; 
  } else { 
  System.err.println("Usage: java DemandPredictor <input.csv> <output.csv>"); 
  System.err.println(" or: java DemandPredictor (uses defaults)"); 
  System.err.println(" or: java DemandPredictor --make-sample"); 
  System.exit(2); 
  return; // unreachable 
  } 

  // Sanity checks on files 
  File inFile = new File(inputPath); 
  if (!inFile.exists() || !inFile.isFile()) { 
  System.err.println("Input file not found: " + inputPath); 
  System.err.println("Tip: run `java DemandPredictor --make-sample` to generate a sample CSV."); 
  System.exit(3); 
  } 
  if (!inFile.canRead()) { 
  System.err.println("Cannot read input file: " + inputPath); 
  System.exit(3); 
  } 

  try { 
  // 1) Read & validate rows → Map<SKU, List<SalesRecord>> 
  Map<String, List<SalesRecord>> data = readCsv(inputPath); 

  if (data.isEmpty()) { 
  System.err.println("No valid rows found in input. Nothing to predict."); 
  System.exit(4); 
  } 

  // 2) Compute predictions 
  Map<String, PredictionResult> results = computePredictions(data); 

  // 3) Write output CSV with stats + 4-week forecast 
  writeOutputCsv(outputPath, results); 

  // 4) Print concise summary 
  printSummary(results, outputPath); 

  } catch (IOException e) { 
  System.err.println("I/O error: " + e.getMessage()); 
  System.exit(5); 
  } catch (RuntimeException e) { 
  // Catch-all to keep flow smooth and provide a clear message. 
  System.err.println("Unexpected error: " + e.getMessage()); 
  System.exit(6); 
  } 
 } 

 // ===== I/O: Read CSV ===== 

 /** 
  * Reads a CSV with columns: SKU_ID,Week_Number,Units_Sold 
  * Performs input validation and skips bad lines with warnings. 
  */ 
 private static Map<String, List<SalesRecord>> readCsv(String path) throws IOException { 
  Map<String, List<SalesRecord>> bySku = new HashMap<>(); 

  try (BufferedReader br = new BufferedReader(new FileReader(path))) { 
  String line; 
  int lineNo = 0; 
  boolean headerProcessed = false; 
  Set<String> seenWeekKeys = new HashSet<>(); // to detect duplicates per SKU-week 

  while ((line = br.readLine()) != null) { 
  lineNo++; 
  if (line.trim().isEmpty()) continue; // skip blank lines 

  // Handle header (best-effort: allow slightly different casing/whitespace) 
  if (!headerProcessed) { 
  headerProcessed = true; 
  String normalized = line.trim().toUpperCase(Locale.ROOT).replace(" ", ""); 
  boolean looksLikeHeader = 
  normalized.startsWith("SKU_ID") || normalized.contains("WEEK_NUMBER"); 
  if (looksLikeHeader) { 
  continue; // skip header row 
  } 
  // else: fall through and treat as data 
  } 

  String[] parts = splitCsvLine(line); 
  if (parts.length != 3) { 
  warn(lineNo, "Expected 3 columns but found " + parts.length + ". Skipping line."); 
  continue; 
  } 

  String rawSku = parts[0].trim(); 
  String rawWeek = parts[1].trim(); 
  String rawUnits = parts[2].trim(); 

  // Validate fields 
  if (rawSku.isEmpty()) { 
  warn(lineNo, "Empty SKU_ID. Skipping line."); 
  continue; 
  } 

  int week; 
  int units; 
  try { 
  week = Integer.parseInt(rawWeek); 
  units = Integer.parseInt(rawUnits); 
  } catch (NumberFormatException nfe) { 
  warn(lineNo, "Week_Number/Units_Sold must be integers. Skipping line."); 
  continue; 
  } 

  if (week <= 0) { 
  warn(lineNo, "Week_Number must be positive. Skipping line."); 
  continue; 
  } 
  if (units < 0) { 
  warn(lineNo, "Units_Sold must be non-negative. Skipping line."); 
  continue; 
  } 

  // Duplicate (SKU,Week) check 
  String dupKey = rawSku + "#" + week; 
  if (seenWeekKeys.contains(dupKey)) { 
  warn(lineNo, "Duplicate (SKU,Week) encountered. Keeping first, skipping this line."); 
  continue; 
  } 
  seenWeekKeys.add(dupKey); 

  bySku.computeIfAbsent(rawSku, k -> new ArrayList<>()) 
  .add(new SalesRecord(rawSku, week, units)); 
  } 
  } 

  // Sort each SKU's records by week ascending 
  for (List<SalesRecord> list : bySku.values()) { 
  list.sort(Comparator.comparingInt(r -> r.weekNumber)); 
  } 

  return bySku; 
 } 

 // Simple CSV split (no quotes/escapes). Sufficient for the stated prompt data. 
 private static String[] splitCsvLine(String line) { 
  return line.split(",", -1); 
 } 

 private static void warn(int lineNo, String msg) { 
  System.err.println("[WARN] line " + lineNo + ": " + msg); 
 } 

 // ===== Forecast Logic ===== 

 /** 
  * For each SKU: 
  * - Take up to the last 8 observed weeks (no zero-filling for missing weeks). 
  * - Compute mean, sample std dev (n>1), coefficient of variation. 
  * - Flag if CV > threshold. 
  * - Predict next 4 weeks as rounded mean. 
  */ 
 private static Map<String, PredictionResult> computePredictions(Map<String, List<SalesRecord>> data) { 
  Map<String, PredictionResult> out = new HashMap<>(); 

  for (Map.Entry<String, List<SalesRecord>> e : data.entrySet()) { 
  String sku = e.getKey(); 
  List<SalesRecord> records = e.getValue(); 

  // Take last <= 8 units 
  int n = records.size(); 
  int start = Math.max(0, n - WEEKS_FOR_AVERAGE); 
  List<Integer> window = new ArrayList<>(Math.min(WEEKS_FOR_AVERAGE, n)); 
  for (int i = start; i < n; i++) { 
  window.add(records.get(i).unitsSold); 
  } 

  PredictionResult pr = new PredictionResult(sku); 

  if (window.isEmpty()) { 
  pr.mean = 0.0; 
  pr.stdDev = 0.0; 
  pr.coeffVar = 0.0; 
  pr.highVariance = false; 
  Arrays.fill(pr.nextWeeks, 0); 
  out.put(sku, pr); 
  continue; 
  } 

  // Mean 
  double sum = 0.0; 
  for (int u : window) sum += u; 
  pr.mean = sum / window.size(); 

  // Sample standard deviation (n > 1) 
  double ssd = 0.0; 
  for (int u : window) { 
  double d = u - pr.mean; 
  ssd += d * d; 
  } 
  if (window.size() > 1) { 
  pr.stdDev = Math.sqrt(ssd / (window.size() - 1)); 
  } else { 
  pr.stdDev = 0.0; 
  } 

  // Coefficient of variation 
  pr.coeffVar = (pr.mean > 0.0) ? (pr.stdDev / pr.mean) : 0.0; 
  pr.highVariance = pr.coeffVar > HIGH_VAR_CV_THRESHOLD; 

  // Naive forecast: repeat rounded mean for each future week 
  int rounded = (int) Math.round(pr.mean); 
  Arrays.fill(pr.nextWeeks, rounded); 

  out.put(sku, pr); 
  } 

  return out; 
 } 

 // ===== I/O: Write CSV ===== 

 /** 
  * Writes a tidy CSV with stats + 4-week predictions. 
  * Columns: 
  * SKU_ID,Average_Demand_Last_8_Weeks,Standard_Deviation,Coefficient_of_Variation, 
  * High_Variance_Flag,Week_1_Prediction,Week_2_Prediction,Week_3_Prediction,Week_4_Prediction 
  */ 
 private static void writeOutputCsv(String path, Map<String, PredictionResult> results) throws IOException { 
  // Sort SKUs alphabetically for consistent output 
  List<String> skus = new ArrayList<>(results.keySet()); 
  Collections.sort(skus); 

  DecimalFormat df = new DecimalFormat("#.##"); 

  try (PrintWriter pw = new PrintWriter(new FileWriter(path))) { 
  pw.println( 
  "SKU_ID,Average_Demand_Last_8_Weeks,Standard_Deviation,Coefficient_of_Variation," + 
  "High_Variance_Flag,Week_1_Prediction,Week_2_Prediction,Week_3_Prediction,Week_4_Prediction" 
  ); 

  for (String sku : skus) { 
  PredictionResult pr = results.get(sku); 
  pw.print(sku); pw.print(","); 
