 // ===== Summary ===== 

 private static void printSummary(Map<String, PredictionResult> results, String outPath) { 
  int total = results.size(); 
  int flagged = 0; 
  double meanOfMeans = 0.0; 
  for (PredictionResult pr : results.values()) { 
  if (pr.highVariance) flagged++; 
  meanOfMeans += pr.mean; 
  } 
  double avgMean = (total > 0) ? (meanOfMeans / total) : 0.0; 

  System.out.println(); 
  System.out.println("=== DEMAND PREDICTION SUMMARY ==="); 
  System.out.println("Output file : " + outPath); 
  System.out.println("Total SKUs processed : " + total); 
  System.out.println("High-variance (CV>50%) : " + flagged + " (" + 
  (total > 0 ? Math.round(100.0 * flagged / total) : 0) + "%)"); 
  System.out.println("Avg of SKU means : " + new DecimalFormat("#.##").format(avgMean)); 
  System.out.println("================================="); 
 } 

