 def personalized_pagerank(reverse_graph, pers, all_concepts, alpha=0.15, tol=1e-6, max_iter=100):
  r = {c: pers.get(c, 0) for c in all_concepts}
  for _ in range(max_iter):
  new_r = {c: alpha * pers.get(c, 0) for c in all_concepts}
  leaked = 0.0
  for u in all_concepts:
  out = len(reverse_graph[u])
  if out == 0:
  leaked += (1 - alpha) * r[u]
  else:
  contrib = (1 - alpha) * r[u] / out
  for v in reverse_graph[u]:
  new_r[v] += contrib
  if leaked > 0:
  total_pers = sum(pers.values())
  if total_pers > 0:
  for c in all_concepts:
  new_r[c] += leaked * (pers.get(c, 0) / total_pers)
  diff = max(abs(new_r[c] - r[c]) for c in all_concepts)
  r = new_r
  if diff < tol:
  break
  return r

 def dijkstra(adj, start, end, all_nodes):
  dist = {node: float('inf') for node in all_nodes}
  dist[start] = 0.0
  prev = {node: None for node in all_nodes}
  pq = [(0.0, start)]
  while pq:
  d, u = heapq.heappop(pq)
  if d > dist[u]:
  continue
  if u in adj:
  for v, cost in adj[u]:
  alt = d + cost
  if alt < dist[v]:
  dist[v] = alt
  prev[v] = u
  heapq.heappush(pq, (alt, v))
  if dist[end] == float('inf'):
  return None
  # recover path
  path = []
  u = end
